import { useState, useEffect } from 'react';
import Post from '../post/Post';
import './videos.scss';

const Videos = () => {
  const [videos, setVideos] = useState([]);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(true);

  const getMediaType = (mediaUrl) => {
    if (!mediaUrl) return null;
    const ext = mediaUrl.split('.').pop().toLowerCase();
    if (['mp4', 'mov'].includes(ext)) return 'video';
    return null;
  };

  const fetchVideos = async () => {
    setLoading(true);
    setError(null);
    try {
      console.log('Videos: Fetching posts');
      const response = await fetch('http://localhost:5000/api/posts');
      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.message || 'Failed to fetch posts');
      }
      const data = await response.json();
      const videoPosts = data.filter((post) => getMediaType(post.media) === 'video');
      console.log('Videos: Filtered video posts=', JSON.stringify(videoPosts, null, 2));
      setVideos(videoPosts);
      setError(null);
    } catch (err) {
      console.error('Videos: Error fetching posts:', err.message, err.response?.data);
      setError(err.message || 'Failed to load videos');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchVideos();
    const handleNewPost = () => {
      console.log('Videos: New post event received');
      fetchVideos();
    };
    window.addEventListener('newPost', handleNewPost);
    return () => window.removeEventListener('newPost', handleNewPost);
  }, []);

  if (loading) return <div className="videos">Loading videos...</div>;
  if (error) return <div className="videos error">{error}</div>;

  return (
    <div className="videos">
      {videos.length === 0 ? (
        <p>No videos available</p>
      ) : (
        videos.map((post) => <Post key={post._id} post={post} />)
      )}
    </div>
  );
};

export default Videos;
